begin;
insert into auth.users(id)select('15000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,7)n;
insert into public.profiles(id,display_name,is_active)select('15000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ACADEMIC fixture '||n,true from generate_series(1,7)n on conflict(id)do update set is_active=true;
insert into public.user_roles(user_id,role)values('15000000-0000-4000-8000-000000000001','dean'),('15000000-0000-4000-8000-000000000002','headmaster'),('15000000-0000-4000-8000-000000000003','teacher'),('15000000-0000-4000-8000-000000000004','discipline_officer'),('15000000-0000-4000-8000-000000000005','student'),('15000000-0000-4000-8000-000000000006','student'),('15000000-0000-4000-8000-000000000007','teacher');
insert into public.school_classes(class_name,grade,academic_year)values('__ACADEMIC_CLASS__','S5','TEST');
insert into public.students(student_id,full_name,class_name,status)select '__ACADEMIC_'||x||'__','Synthetic '||x,'__ACADEMIC_CLASS__','Active'from unnest(array['A','B','C','D','E'])x;
update public.students set auth_user_id='15000000-0000-4000-8000-000000000005'where student_id='__ACADEMIC_B__';
insert into public.teacher_class_assignments(teacher_user_id,class_name)values('15000000-0000-4000-8000-000000000003','__ACADEMIC_CLASS__');
create temporary table academic_test(data jsonb,release_id uuid);
insert into academic_test(data)values(jsonb_build_object('class_name','__ACADEMIC_CLASS__','release_name','Beginning of term tests','recorded_on',(now()at time zone'Africa/Kigali')::date,'source_filename','synthetic.csv','subjects','[{"name":"Subject A","maximum":40},{"name":"Subject B","maximum":60}]'::jsonb,'rows','[{"student_id":"__ACADEMIC_A__","marks":{"Subject A":39,"Subject B":40},"overall":80},{"student_id":"__ACADEMIC_B__","marks":{"Subject A":null,"Subject B":42},"overall":70},{"student_id":"__ACADEMIC_C__","marks":{"Subject A":28,"Subject B":42},"overall":70},{"student_id":"__ACADEMIC_D__","marks":{"Subject A":0,"Subject B":0},"overall":0},{"student_id":"__ACADEMIC_E__","marks":{"Subject A":40,"Subject B":60},"overall":null}]'::jsonb));
grant all on academic_test to authenticated;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000001',true);
set local role authenticated;
do $$declare d jsonb:=(select data from academic_test);p jsonb;id uuid;again uuid;begin
 p:=public.academic_preview(d);
 begin perform public.academic_preview(jsonb_set(d,'{rows,1}',d->'rows'->0));raise exception 'FAIL duplicate result IDs';exception when raise_exception then if sqlerrm='FAIL duplicate result IDs'then raise;end if;end;
 begin perform public.academic_preview(jsonb_set(d,'{rows,0,marks,Subject A}','41'));raise exception 'FAIL out-of-range score';exception when raise_exception then if sqlerrm='FAIL out-of-range score'then raise;end if;end;
 begin perform public.academic_preview(jsonb_set(d,'{rows,0,overall}','101'));raise exception 'FAIL overall above 100';exception when raise_exception then if sqlerrm='FAIL overall above 100'then raise;end if;end;
 begin perform public.academic_preview(jsonb_set(d,'{subjects,0,maximum}','0'));raise exception 'FAIL zero maximum';exception when raise_exception then if sqlerrm='FAIL zero maximum'then raise;end if;end;
 begin perform public.academic_preview(jsonb_set(d,'{rows}',(d->'rows')-4));raise exception 'FAIL partial class upload';exception when raise_exception then if sqlerrm='FAIL partial class upload'then raise;end if;end;
 begin perform public.academic_publish(d,'tampered','45000000-0000-4000-8000-000000000009','Reviewed');raise exception 'FAIL tampered preview';exception when serialization_failure then null;end;
 if jsonb_array_length(p->'warnings')<>3 then raise exception 'FAIL missing/mismatch warnings';end if;
 if not exists(select 1 from jsonb_array_elements(p->'rows')r where r->>'student_id'='__ACADEMIC_D__'and(r->>'overall')::numeric=0 and(r->>'rank')::integer=4 and(r->>'calculated')::numeric=0)then raise exception 'FAIL zero preserved and ranked';end if;
 if not exists(select 1 from jsonb_array_elements(p->'rows')r where r->>'student_id'='__ACADEMIC_B__'and(r->>'rank')::integer=2 and r->>'calculated'is null)then raise exception 'FAIL missing subject keeps supplied overall rank';end if;
 if not exists(select 1 from jsonb_array_elements(p->'rows')r where r->>'student_id'='__ACADEMIC_C__'and(r->>'rank')::integer=2 and(r->>'calculated')::numeric=70)then raise exception 'FAIL weighted maxima and tie';end if;
 if not exists(select 1 from jsonb_array_elements(p->'rows')r where r->>'student_id'='__ACADEMIC_E__'and r->>'rank'is null and(r->>'calculated')::numeric=100)then raise exception 'FAIL missing overall no invented rank';end if;
 begin perform public.academic_publish(d,p->>'preview_token','45000000-0000-4000-8000-000000000001',null);raise exception 'FAIL warnings bypass';exception when raise_exception then if sqlerrm='FAIL warnings bypass'then raise;end if;end;
 id:=public.academic_publish(d,p->>'preview_token','45000000-0000-4000-8000-000000000001','Missing test awaiting school review; supplied total confirmed.');
 again:=public.academic_publish(d,p->>'preview_token','45000000-0000-4000-8000-000000000001','Missing test awaiting school review; supplied total confirmed.');if again<>id then raise exception 'FAIL idempotent retry';end if;
 p:=public.academic_preview(d||'{"source_filename":"same-file-renamed.csv"}');
 again:=public.academic_publish(d||'{"source_filename":"same-file-renamed.csv"}',p->>'preview_token','45000000-0000-4000-8000-000000000002','Confirmed');
 if again<>id then raise exception 'FAIL duplicate source after rename';end if;
 update academic_test set release_id=id;
 begin perform public.academic_publish(d||'{"release_name":"Different"}',p->>'preview_token','45000000-0000-4000-8000-000000000001','Different');raise exception 'FAIL changed retry';exception when raise_exception then if sqlerrm='FAIL changed retry'then raise;end if;end;
 perform public.refresh_school_concerns();
 if not exists(select 1 from public.school_concerns where student_id='__ACADEMIC_D__'and category='academic'and(evidence->>'percentage')::numeric=0)then raise exception 'FAIL named release concerns';end if;
 if exists(select 1 from public.school_concerns where student_id='__ACADEMIC_E__'and category='academic')then raise exception 'FAIL missing overall treated as zero';end if;
end $$;
reset role;
do $$begin
 if(select count(*)from public.academic_releases where class_name='__ACADEMIC_CLASS__')<>1 then raise exception 'FAIL double publication';end if;
 if(select count(*)from public.school_notifications where recipient_id='15000000-0000-4000-8000-000000000002'and action='academic_release_published')<>1 then raise exception 'FAIL headmaster notification';end if;
end $$;
-- Correct the original cohort even after the class has moved to a new year.
update public.students set status='Archived'where student_id='__ACADEMIC_B__';
update public.school_classes set academic_year='NEXT'where class_name='__ACADEMIC_CLASS__';
insert into public.students(student_id,full_name,class_name)values('__ACADEMIC_NEW__','New-year student','__ACADEMIC_CLASS__');
set local role authenticated;
do $$declare d jsonb:=(select data||jsonb_build_object('replaces_id',release_id)from academic_test);p jsonb;id uuid;old_id uuid:=(select release_id from academic_test);begin
 d:=jsonb_set(d,'{rows,0,marks,Subject A}','38');d:=jsonb_set(d,'{rows,0,marks,Subject B}','50');d:=jsonb_set(d,'{rows,0,overall}','88');p:=public.academic_preview(d);
 if p->>'academic_year'<>'TEST'or jsonb_array_length(p->'rows')<>5 then raise exception 'FAIL original year/cohort';end if;
 id:=public.academic_publish(d,p->>'preview_token','45000000-0000-4000-8000-000000000003','Original cohort; missing records still under review.');
 if(public.academic_release_detail(old_id,true)->'rows'->0->>'overall')::numeric<>80 then raise exception 'FAIL old version mutated';end if;
 if jsonb_array_length(public.academic_release_detail(id,false)->'rows')<>4 or jsonb_array_length(public.academic_release_detail(id,true)->'rows')<>5 then raise exception 'FAIL current versus historical filter';end if;
 begin perform public.academic_preview(d);raise exception 'FAIL duplicate correction';exception when serialization_failure then null;end;
 begin insert into public.import_batches(import_type,status,source_filename,created_by)values('academics','applied','forged.csv',auth.uid());raise exception 'FAIL forged academic batch';exception when insufficient_privilege then null;end;
 begin update public.academic_records set score=0 where student_id='__ACADEMIC_A__';raise exception 'FAIL legacy direct score edit';exception when insufficient_privilege then null;end;
 begin update public.academic_release_results set overall=100 where release_id=id;raise exception 'FAIL direct result edit';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000005',true);
set local role authenticated;
do $$declare r jsonb;begin
 r:=public.my_student_records();if jsonb_array_length(r->'releases')<>2 then raise exception 'FAIL own result history';end if;
 if(r->'releases')::text like'%Synthetic A%'or(r->'releases')::text like'%__ACADEMIC_A__%'then raise exception 'FAIL peers leaked';end if;
 if(r->'releases'->0->>'rank')::integer<>2 then raise exception 'FAIL own rank';end if;
 begin perform public.academic_release_list('__ACADEMIC_CLASS__');raise exception 'FAIL student class results';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000003',true);
set local role authenticated;
do $$begin if jsonb_array_length(public.academic_release_list('__ACADEMIC_CLASS__'))<>2 then raise exception 'FAIL assigned teacher read';end if;begin perform public.academic_preview((select data from academic_test));raise exception 'FAIL teacher publish';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000004',true);
set local role authenticated;
do $$begin begin perform public.academic_release_list('__ACADEMIC_CLASS__');raise exception 'FAIL officer academic read';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000007',true);
set local role authenticated;
do $$begin begin perform public.academic_release_list('__ACADEMIC_CLASS__');raise exception 'FAIL unassigned teacher read';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','15000000-0000-4000-8000-000000000002',true);
set local role authenticated;
do $$begin if jsonb_array_length(public.academic_release_list('__ACADEMIC_CLASS__'))<>2 then raise exception 'FAIL Headmaster read';end if;begin perform public.academic_preview((select data from academic_test));raise exception 'FAIL Headmaster acting as Dean';exception when insufficient_privilege then null;end;end $$;
reset role;
rollback;
